// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 8: Read the open items": "in1_Step8Readtheopenitems"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 8: Read the open items";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"post_body": JSON.stringify({ to: $('Config').first().json.escalation_owner, subject: 'Overdue exception items, oldest first', items: out.items, text: out.text })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 8: open items past the aging limit, in working days, oldest first.
const cfg = $('Config').first().json;
const day = d => new Date(String(d).slice(0, 10) + 'T00:00:00Z');
const today = day(new Date().toISOString());
const working = from => { let n = 0; for (let d = new Date(from.getTime() + 86400000); d <= today; d = new Date(d.getTime() + 86400000)) if (d.getUTCDay() % 6 !== 0) n++; return n; };
const items = ($('Step 8: Read the open items').first().json.items || []).filter(i => i.status === 'open' && i.raised_at)
  .map(i => Object.assign({}, i, { age: working(day(i.raised_at)) }))
  .filter(i => i.age > Number(cfg.aging_limit_days))
  .sort((a, b) => day(a.raised_at) - day(b.raised_at));
return [{ json: { any: items.length > 0, items: items.map(i => i.id),
  text: items.map(i => `${i.id}: invoice ${i.invoice_id}, ${i.reason_code}, owner ${i.owner || 'none'}, ${i.age} working days`).join('\n') } }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));
